CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), email text NOT NULL, name text NOT NULL, password_hash text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,email));
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, slug text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,slug));
CREATE TABLE permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE, description text);
CREATE TABLE user_roles (profile_id uuid REFERENCES profiles(id) ON DELETE CASCADE, role_id uuid REFERENCES roles(id) ON DELETE CASCADE, PRIMARY KEY(profile_id,role_id));
CREATE TABLE role_permissions (role_id uuid REFERENCES roles(id) ON DELETE CASCADE, permission_id uuid REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id,permission_id));
CREATE TABLE brand_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL UNIQUE REFERENCES organizations(id), name text NOT NULL, tagline text, logo_url text, primary_color text NOT NULL DEFAULT '#07182D', secondary_color text NOT NULL DEFAULT '#123B63', accent_color text NOT NULL DEFAULT '#C79A45', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE authors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, slug text NOT NULL, bio text, avatar_url text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,slug));
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, slug text NOT NULL, description text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,slug));
CREATE TABLE municipalities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, state text NOT NULL, slug text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,slug));
CREATE TYPE article_status AS ENUM ('draft','review','approved','scheduled','published','update_needed','archived');
CREATE TABLE articles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), author_id uuid REFERENCES authors(id), category_id uuid REFERENCES categories(id), municipality_id uuid REFERENCES municipalities(id), title text NOT NULL, slug text NOT NULL, excerpt text, content_html text NOT NULL DEFAULT '', status article_status NOT NULL DEFAULT 'draft', seo_title text, seo_description text, canonical_url text, featured_image_url text, published_at timestamptz, scheduled_at timestamptz, created_by uuid REFERENCES profiles(id), updated_by uuid REFERENCES profiles(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, UNIQUE(organization_id,slug));
CREATE TABLE article_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), article_id uuid NOT NULL REFERENCES articles(id) ON DELETE CASCADE, version integer NOT NULL, title text NOT NULL, content_html text NOT NULL, created_by uuid REFERENCES profiles(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(article_id,version));
CREATE TABLE media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), url text NOT NULL, filename text NOT NULL, mime_type text, alt_text text, caption text, credit text, focal_x numeric, focal_y numeric, folder text, created_by uuid REFERENCES profiles(id), created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE home_blocks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), block_type text NOT NULL, title text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, position integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, starts_at timestamptz, ends_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text, email text, phone text, source text, status text NOT NULL DEFAULT 'new', consent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE lead_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES leads(id) ON DELETE CASCADE, status text NOT NULL, notes text, created_by uuid REFERENCES profiles(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), profile_id uuid REFERENCES profiles(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_articles_org_status ON articles(organization_id,status);
CREATE INDEX idx_articles_published ON articles(published_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX idx_media_org ON media(organization_id,created_at DESC);
CREATE INDEX idx_leads_org_status ON leads(organization_id,status);
CREATE INDEX idx_audit_org_created ON audit_log(organization_id,created_at DESC);
